//! Every reader must return the same values as the CSV reference for the 48-row fixture set
//! generated by `bench/make_datasets.py --fixture tests/fixtures`.

use chartmate_io::{read_dataset, DatasetPreview};

fn fixture(name: &str) -> String {
    format!("{}/tests/fixtures/{}", env!("CARGO_MANIFEST_DIR"), name)
}

fn load(name: &str) -> DatasetPreview {
    read_dataset(fixture(name), None).unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn col(p: &DatasetPreview, name: &str) -> Vec<String> {
    let i = p
        .columns
        .iter()
        .position(|c| c.eq_ignore_ascii_case(name))
        .unwrap_or_else(|| panic!("column {name} missing in {:?} ({})", p.columns, p.detected_sep));
    p.rows.iter().map(|r| r[i].clone()).collect()
}

fn nums(v: &[String]) -> Vec<f64> {
    v.iter().map(|s| s.parse::<f64>().unwrap_or(f64::NAN)).collect()
}

fn assert_close(name: &str, got: &[f64], want: &[f64], tol: f64) {
    assert_eq!(got.len(), want.len(), "{name}: length");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!((g - w).abs() <= tol, "{name}[{i}]: got {g}, want {w}");
    }
}

/// (file, timestamp column, t_air column, power column)
const CASES: &[(&str, &str, &str, &str)] = &[
    ("sample.xlsx", "timestamp", "t_air", "power_kw"),
    ("sample.ods", "timestamp", "t_air", "power_kw"),
    ("sample.parquet", "timestamp", "t_air", "power_kw"),
    ("sample.h5", "time", "t_air", "power_kw"),
    ("sample.nc", "time", "t_air", "power_kw"),
    ("sample_classic.nc", "time", "t_air", "power_kw"),
    ("sample.mat", "time", "t_air", "power_kw"),
    ("sample_v73.mat", "time", "t_air", "power_kw"),
    ("sample.sav", "timestamp", "t_air", "power_kw"),
    ("sample_v5.xpt", "time", "t_air", "power_kw"),
    ("sample_v8.xpt", "timestamp", "t_air", "power_kw"),
    ("sample.fits", "timestamp", "t_air", "power_kw"),
];

#[test]
fn all_formats_match_csv_reference() {
    let reference = load("sample.csv");
    assert_eq!(reference.rows.len(), 48);
    let ts_ref = col(&reference, "timestamp");
    let t_ref = nums(&col(&reference, "t_air"));
    let p_ref = nums(&col(&reference, "power_kw"));

    for (file, ts, t, p) in CASES {
        let got = load(file);
        assert_eq!(got.rows.len(), 48, "{file}: row count ({})", got.detected_sep);
        assert!(!got.truncated, "{file}: unexpectedly truncated");
        // f32 is never used by the generator, so values must match to the printed precision.
        assert_close(&format!("{file}:t_air"), &nums(&col(&got, t)), &t_ref, 1e-9);
        assert_close(&format!("{file}:power"), &nums(&col(&got, p)), &p_ref, 1e-9);
        let ts_got = col(&got, ts);
        // Parquet stores the pandas timestamp as int64 µs/ns; all others must give ISO text.
        if !file.ends_with(".parquet") {
            assert_eq!(ts_got, ts_ref, "{file}: timestamps");
            assert_eq!(got.suggested_ts_col.as_deref(), Some(ts_got_name(&got, ts)), "{file}: ts detection");
        }
    }
}

fn ts_got_name<'a>(p: &'a DatasetPreview, name: &str) -> &'a str {
    p.columns.iter().find(|c| c.eq_ignore_ascii_case(name)).map(|s| s.as_str()).unwrap()
}

#[test]
fn text_columns_survive() {
    for file in ["sample.csv", "sample.xlsx", "sample.ods", "sample.sav", "sample_v8.xpt", "sample.fits"] {
        let p = load(file);
        let z = col(&p, "zone");
        assert_eq!(&z[..4], &["Z1", "Z2", "Z3", "Z4"], "{file}");
    }
}

#[test]
fn sas7bdat_reference_fixture() {
    // Reference file shipped with the `sas7bdat` crate (MIT).
    let p = load("people_nonascii.sas7bdat");
    assert!(!p.columns.is_empty());
    assert!(!p.rows.is_empty());
    assert!(p.detected_sep.starts_with("SAS7BDAT"));
}

#[test]
fn row_limit_sets_truncation_flag() {
    let opts = chartmate_io::ParseOptions {
        separator: None,
        decimal: None,
        timestamp_col: None,
        timestamp_format: None,
        max_rows: Some(10),
    };
    for file in ["sample.csv", "sample.h5", "sample.sav", "sample.xlsx"] {
        let p = read_dataset(fixture(file), Some(chartmate_io::ParseOptions { ..opts.clone() })).unwrap();
        assert_eq!(p.rows.len(), 10, "{file}");
        assert_eq!(p.total_rows, 48, "{file}");
        assert!(p.truncated, "{file}");
        assert!(!p.notes.is_empty(), "{file}: missing truncation note");
    }
}
